/**
 * A planet's clouds and their shadows, drawn — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of `ShaderMaterial` and
 * `MaterialPluginBase` for a planet's clouds, loaded only by dynamic
 * `import()` from the planet view, so a world without clouds never fetches it.
 *
 * Each layer is one sphere at its height around the planet's centre, seen
 * from both sides, so its clouds are overhead from the ground and over the
 * ground from above. Each fragment works out, as the processor's reference
 * does (clouds.ts), how much cloud lies along its direction from the centre in
 * the planet's own frame (so the clouds stay put as the scene's origin moves),
 * turned by the wind; and lights it by the sun's height there. Seen from under
 * the layer, the thick middle of a cloud is darker than its edges; and
 * distant cloud fades into the haze, summed along the eye's line as the
 * ground's is (the air's veil, atmosphereChunk.ts). On the night side
 * clouds are faint.
 *
 * The shadows are a material plugin on every lit material in the scene: each
 * fragment follows the sun's ray up through the layers over it and keeps from
 * the sun's direct light what their cloud there keeps, so the ground, the
 * blocks and whatever stands on them are shaded alike. A physically based
 * material loses only its direct light; the sky's still reaches it.
 *
 * As skyChunk.ts does, every shader is written in WGSL for WebGPU and GLSL
 * for WebGL2, chosen by engine kind; the cloud noise is written once in each
 * and shared by the clouds and their shadows.
 */
import { ShaderMaterial } from '@babylonjs/core/Materials/shaderMaterial';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import { CreateSphere } from '@babylonjs/core/Meshes/Builders/sphereBuilder';
import { RenderTargetTexture } from '@babylonjs/core/Materials/Textures/renderTargetTexture';
import { Constants } from '@babylonjs/core/Engines/constants';
import { Color3, Color4 } from '@babylonjs/core/Maths/math.color';
import { Matrix, Vector2, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import { DepthRenderer } from '@babylonjs/core/Rendering/depthRenderer';
import type { Scene } from '@babylonjs/core/scene';
import type { UniformBuffer } from '@babylonjs/core/Materials/uniformBuffer';
import { CLOUD_DEPTH_TRUSTED_M, cloudTargetSize, type CloudLayer } from './clouds';
import { CLOUD_BASE_GLSL, CLOUD_BASE_WGSL, MAX_OCTAVES, NOISE_GLSL, NOISE_WGSL } from './cloudNoiseSource';
import type { CloudShadowsHandle, CloudsHandle } from './planetView';
import { testCutoutsByTheirPicture } from './cutoutDepth';
import { addMeshReadyCheck } from './meshReadiness';
import { materialArrivals } from './materialArrivals';
import { isAway, takePlugin } from './awayMaterials';

/** Every input the clouds' shader takes, in both languages. */
export const CLOUD_UNIFORMS = [
  'world',
  'worldViewProjection',
  'eye',
  'centre',
  'toPlanet',
  'sunDirection',
  'radius',
  'cover',
  'size',
  'wind',
  'time',
  'cloudColor',
  'opacity',
  'octaves',
  'hazeBeta',
  'hazeHeight',
  'planetRadius',
  'baseVariety',
] as const;

/** Every input the shadows take, in both languages: up to four layers, one in each component of the vec4s. */
export const CLOUD_SHADOW_UNIFORMS = [
  'cloudShadowCentre',
  'cloudShadowToPlanet',
  'cloudShadowSun',
  'cloudShadowTime',
  'cloudShadowOctaves',
  'cloudShadowRadius',
  'cloudShadowCover',
  'cloudShadowSize',
  'cloudShadowWind',
  'cloudShadowStrength',
] as const;

/** The most layers the shadows follow. */
const MAX_SHADOW_LAYERS = 4;
/** Layers of noise in a shadow: its edge is soft, and the ground under it far below. */
const SHADOW_OCTAVES = 3;
/** Drawn after every other see-through surface: the water under them. */
const CLOUD_ALPHA_INDEX = 10;
/**
 * How far a sheet seen from outside is pulled toward the eye, in the least
 * steps the depth can tell apart: enough to stand in front of its planet's own
 * ground from far off, where the two are closer than a few steps, and far too
 * little to pass the ground of a nearer planet.
 */
const OUTSIDE_DEPTH_UNITS = 64;


// ---- The clouds: GLSL (WebGL2) ----
const VERTEX_GLSL = `
precision highp float;
attribute vec3 position;
uniform mat4 world;
uniform mat4 worldViewProjection;
varying vec3 vWorld;
void main(void) {
  vWorld = (world * vec4(position, 1.0)).xyz;
  gl_Position = worldViewProjection * vec4(position, 1.0);
}`;

const FRAGMENT_GLSL = `
precision highp float;
varying vec3 vWorld;
uniform vec3 eye;
uniform vec3 centre;
uniform mat4 toPlanet;
uniform vec3 sunDirection;
uniform float radius;
uniform float cover;
uniform float size;
uniform float wind;
uniform float time;
uniform vec3 cloudColor;
uniform float opacity;
uniform float octaves;
uniform float hazeBeta;
uniform float hazeHeight;
uniform float planetRadius;
uniform float baseVariety;
${NOISE_GLSL}
${CLOUD_BASE_GLSL}
// The haze along a line, the altitude changing evenly from a0 to a1, as the air's veil sums it on the ground.
float cloudHazeDepth(float a0, float a1, float len) {
  if (hazeBeta <= 0.0 || len <= 0.0) return 0.0;
  float u0 = max(a0, 0.0) / hazeHeight;
  float u1 = max(a1, 0.0) / hazeHeight;
  float du = u1 - u0;
  if (abs(du) < 1e-4) return hazeBeta * len * exp(-u0);
  return hazeBeta * len * (exp(-u0) - exp(-u1)) / du;
}
void main(void) {
  if (cover <= 0.0) discard;
  vec3 up = normalize(vWorld - centre);
  vec3 d = normalize((toPlanet * vec4(up, 0.0)).xyz);
  float density = cloudDensityOf(d, radius, cover, size, wind, time, octaves);
  if (density <= 0.001) discard;
  float sunUp = dot(up, normalize(sunDirection));
  float day = smoothstep(-0.1, 0.2, sunUp);
  float warm = 1.0 - smoothstep(0.0, 0.3, sunUp);
  vec3 night = vec3(0.12, 0.13, 0.17);
  vec3 light = (night + (cloudColor - night) * day) * (vec3(1.0) - warm * (vec3(1.0) - vec3(1.0, 0.62, 0.42)));
  float alpha = density * opacity * (0.35 + 0.65 * day);
  // From under the layer, a cloud's thick middle is darker, and a cloud whose base lies lower darker than one whose base is high.
  if (length(eye - centre) < radius) {
    float lift = baseVariety > 0.0 ? cloudBaseOf(d, radius, size, wind, time, baseVariety, density) / (baseVariety * 0.45) : 0.5;
    light *= cloudUndersideOf(density, lift, baseVariety);
  }
  // Far cloud is lost in the haze between, summed along the eye's line as the ground's is.
  float hd = cloudHazeDepth(length(eye - centre) - planetRadius, length(vWorld - centre) - planetRadius, length(vWorld - eye));
  alpha *= exp(-hd * hd * 1.4427);
  gl_FragColor = vec4(light, alpha);
}`;

// ---- The clouds: WGSL (WebGPU), the same sums in Babylon's WGSL ShaderMaterial dialect. ----
const VERTEX_WGSL = `
attribute position: vec3f;
uniform world: mat4x4f;
uniform worldViewProjection: mat4x4f;
varying vWorld: vec3f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  vertexOutputs.vWorld = (uniforms.world * vec4f(vertexInputs.position, 1.0)).xyz;
  vertexOutputs.position = uniforms.worldViewProjection * vec4f(vertexInputs.position, 1.0);
}`;

const FRAGMENT_WGSL = `
varying vWorld: vec3f;
uniform eye: vec3f;
uniform centre: vec3f;
uniform toPlanet: mat4x4f;
uniform sunDirection: vec3f;
uniform radius: f32;
uniform cover: f32;
uniform size: f32;
uniform wind: f32;
uniform time: f32;
uniform cloudColor: vec3f;
uniform opacity: f32;
uniform octaves: f32;
uniform hazeBeta: f32;
uniform hazeHeight: f32;
uniform planetRadius: f32;
uniform baseVariety: f32;
${NOISE_WGSL}
${CLOUD_BASE_WGSL}
fn cloudHazeDepth(a0: f32, a1: f32, len: f32) -> f32 {
  if (uniforms.hazeBeta <= 0.0 || len <= 0.0) { return 0.0; }
  let u0 = max(a0, 0.0) / uniforms.hazeHeight;
  let u1 = max(a1, 0.0) / uniforms.hazeHeight;
  let du = u1 - u0;
  if (abs(du) < 1e-4) { return uniforms.hazeBeta * len * exp(-u0); }
  return uniforms.hazeBeta * len * (exp(-u0) - exp(-u1)) / du;
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  if (uniforms.cover <= 0.0) { discard; }
  let up = normalize(input.vWorld - uniforms.centre);
  let d = normalize((uniforms.toPlanet * vec4f(up, 0.0)).xyz);
  let density = cloudDensityOf(d, uniforms.radius, uniforms.cover, uniforms.size, uniforms.wind, uniforms.time, uniforms.octaves);
  if (density <= 0.001) { discard; }
  let sunUp = dot(up, normalize(uniforms.sunDirection));
  let day = smoothstep(-0.1, 0.2, sunUp);
  let warm = 1.0 - smoothstep(0.0, 0.3, sunUp);
  let night = vec3f(0.12, 0.13, 0.17);
  var light = (night + (uniforms.cloudColor - night) * day) * (vec3f(1.0) - warm * (vec3f(1.0) - vec3f(1.0, 0.62, 0.42)));
  var alpha = density * uniforms.opacity * (0.35 + 0.65 * day);
  if (length(uniforms.eye - uniforms.centre) < uniforms.radius) {
    var lift: f32 = 0.5;
    if (uniforms.baseVariety > 0.0) { lift = cloudBaseOf(d, uniforms.radius, uniforms.size, uniforms.wind, uniforms.time, uniforms.baseVariety, density) / (uniforms.baseVariety * 0.45); }
    light *= cloudUndersideOf(density, lift, uniforms.baseVariety);
  }
  let hd = cloudHazeDepth(length(uniforms.eye - uniforms.centre) - uniforms.planetRadius, length(input.vWorld - uniforms.centre) - uniforms.planetRadius, length(input.vWorld - uniforms.eye));
  alpha *= exp(-hd * hd * 1.4427);
  fragmentOutputs.color = vec4f(light, alpha);
}`;

// ---- The clouds as volumes (the high tiers): marched through each layer's shell. ----

/** Every input the volume's shader takes, in both languages. */
export const CLOUD_VOLUME_UNIFORMS = [...CLOUD_UNIFORMS, 'thickness', 'steps', 'lightSteps'] as const;

/** The most steps either volume shader marches, along the eye's line and toward the sun; `steps` and `lightSteps` choose fewer. */
const MAX_VOLUME_STEPS = 168;
const MAX_VOLUME_LIGHT_STEPS = 8;

const VOLUME_FRAGMENT_GLSL = `
precision highp float;
varying vec3 vWorld;
uniform vec3 eye;
uniform vec3 centre;
uniform mat4 toPlanet;
uniform vec3 sunDirection;
uniform float radius;
uniform float thickness;
uniform float cover;
uniform float size;
uniform float wind;
uniform float time;
uniform vec3 cloudColor;
uniform float opacity;
uniform float octaves;
uniform float hazeBeta;
uniform float hazeHeight;
uniform float planetRadius;
uniform float baseVariety;
uniform float steps;
uniform float lightSteps;
${NOISE_GLSL}
${CLOUD_BASE_GLSL}
float cloudHazeDepth(float a0, float a1, float len) {
  if (hazeBeta <= 0.0 || len <= 0.0) return 0.0;
  float u0 = max(a0, 0.0) / hazeHeight;
  float u1 = max(a1, 0.0) / hazeHeight;
  float du = u1 - u0;
  if (abs(du) < 1e-4) return hazeBeta * len * exp(-u0);
  return hazeBeta * len * (exp(-u0) - exp(-u1)) / du;
}
vec2 cloudSphereHit(vec3 o, vec3 d, float r) {
  float b = dot(o, d);
  float c = dot(o, o) - r * r;
  float disc = b * b - c;
  if (disc < 0.0) return vec2(1e20, -1e20);
  float s = sqrt(disc);
  return vec2(-b - s, -b + s);
}
// How dense the cloud is at p (from the planet's centre, in the scene's axes), as the reference's cloudVolumeDensity.
float cloudVolume(vec3 p) {
  float r = length(p);
  float h = (r - radius) / thickness;
  if (h < 0.0 || h > 1.0) return 0.0;
  vec3 d = normalize((toPlanet * vec4(p / r, 0.0)).xyz);
  float c = cloudDensityOf(d, radius, cover, size, wind, time, 4.0);
  if (c <= 0.0) return 0.0;
  // The column stands from its own base to the shell's top, its shape squeezed to fit.
  float b = cloudBaseOf(d, radius, size, wind, time, baseVariety, c);
  float hc = (h - b) / (1.0 - b);
  if (hc < 0.0) return 0.0;
  float turn = time * wind / radius;
  float cs = cos(turn);
  float sn = sin(turn);
  vec3 pp = (toPlanet * vec4(p, 0.0)).xyz;
  vec3 q = vec3(pp.x * cs + pp.z * sn, pp.y, pp.z * cs - pp.x * sn) * (8.3 / size);
  float n = (cloudValueNoise(q) + 0.5 * cloudValueNoise(q * 2.0) + 0.25 * cloudValueNoise(q * 4.0)) / 1.75;
  // The detail heaps the tops unevenly and tears the edges.
  float top = 0.25 + 0.75 * c - 0.25 * n;
  float base = c * smoothstep(0.0, 0.07, hc) * (1.0 - smoothstep(top - 0.25, top, hc));
  if (base <= 0.0) return 0.0;
  return clamp((base - n * 0.45) / (1.0 - 0.45), 0.0, 1.0);
}
// Light scattered at an angle whose cosine is mu: Henyey-Greenstein, times four pi so that light scattered evenly is 1.
#ifdef CLOUD_DEPTH_CULL
uniform sampler2D cloudDepth;
uniform vec2 cloudDepthSize;
uniform vec3 cameraForward;
// Whether the ground stands in front of the shell (shellZ ahead of the camera) at this pixel and at every one around it.
// The lay-over reads a pixel of the target only for the screen's pixels around it, so where all nine are ground, no pixel of sky reads it.
bool cloudGroundInFront(float shellZ) {
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      float z = texture2D(cloudDepth, (gl_FragCoord.xy + vec2(float(x), float(y))) / cloudDepthSize).r;
      if (z <= 0.0 || z >= shellZ || z >= ${CLOUD_DEPTH_TRUSTED_M.toFixed(1)}) return false;
    }
  }
  return true;
}
#endif
float cloudPhase(float mu, float g) {
  float g2 = g * g;
  return (1.0 - g2) / pow(1.0 + g2 - 2.0 * g * mu, 1.5);
}
void main(void) {
  if (cover <= 0.0) discard;
  vec3 o = eye - centre;
  vec3 dir = normalize(vWorld - eye);
  vec2 outer = cloudSphereHit(o, dir, radius + thickness);
  if (outer.y <= 0.0) discard;
  vec2 inner = cloudSphereHit(o, dir, radius);
  vec2 ground = cloudSphereHit(o, dir, planetRadius);
  // One stretch of the shell along the line: from the eye, where it leaves the inner sphere below the layer, or where it enters the outer from above;
  // to where it leaves the outer, meets the inner from above, or meets the planet.
  float t0 = max(outer.x, 0.0);
  if (length(o) < radius) t0 = inner.y;
  float t1 = outer.y;
  if (inner.x > t0 && inner.x < t1) t1 = inner.x;
  if (ground.x > 0.0 && ground.x < t1) t1 = ground.x;
  t1 = min(t1, t0 + 20000.0);
  if (t1 <= t0) discard;
#ifdef CLOUD_DEPTH_CULL
  if (cloudGroundInFront(t0 * dot(dir, cameraForward))) discard;
#endif
  vec3 sun = normalize(sunDirection);
  float mu = dot(dir, sun);
  float phase = mix(cloudPhase(mu, -0.24), cloudPhase(mu, 0.62), 0.7);
  // Two speeds: long strides through clear air, and once in cloud, back a stride and short steps through it.
  float coarse = clamp((t1 - t0) / steps, 50.0, 800.0);
  float fine = clamp(thickness * 1.2 / steps, 15.0, 200.0);
  // Each pixel starts a little further along than its neighbours, at random, so the strides' bands become an even grain.
  float jitter = cloudHash(vec3(gl_FragCoord.xy, 17.0));
  float t = t0 + coarse * jitter;
  bool inCloud = false;
  float clearRun = 0.0;
  float found = t0;
  // Seen from well outside the shell, where fine steps show little, half the steps.
  float budget = steps * (length(o) > radius + thickness * 5.0 ? 1.5 : 3.0);
  float T = 1.0;
  vec3 S = vec3(0.0);
  float firstHit = -1.0;
  vec3 night = vec3(0.12, 0.13, 0.17);
  float lightStep = thickness * 0.6 / lightSteps;
  for (int i = 0; i < ${MAX_VOLUME_STEPS}; i++) {
    if (float(i) >= budget || t > t1) break;
    vec3 p = o + dir * t;
    float dens = cloudVolume(p);
    // Four short steps at the eye, longer by a twentieth of the way gone: a longer stride near the eye steps over a
    // grazed thin cloud top for some pixels' starts and not others, dotting its outline with the shaded cloud behind.
    float stride = min(coarse, fine * 4.0 + (t - t0) * 0.05);
    if (!inCloud) {
      if (dens <= 0.003) { t += stride; continue; }
      inCloud = true;
      clearRun = 0.0;
      found = t;
      t = max(t - stride, t0);
      continue;
    }
    float dt = fine;
    if (dens <= 0.003) {
      // Clear air short of where the stride found cloud does not count toward leaving it: given up there,
      // the march would land back in that cloud's edge, back up again, and spend every step it has.
      if (t > found) clearRun += 1.0;
      if (clearRun > 4.0) inCloud = false;
    } else {
      clearRun = 0.0;
      if (firstHit < 0.0) firstHit = t;
      float sigma = dens * 0.015 * opacity;
      // How much of the sun reaches this point through the cloud toward it.
      float toward = 0.0;
      for (int j = 0; j < ${MAX_VOLUME_LIGHT_STEPS}; j++) {
        if (float(j) >= lightSteps) break;
        toward += cloudVolume(p + sun * lightStep * (float(j) + 0.5)) * lightStep;
      }
      float beer = exp(-toward * 0.015 * opacity);
      // The powder darkening: the inside of a cloud facing the sun is less bright than its sunlit edge.
      float powder = 1.0 - exp(-dens * 6.0);
      vec3 up = normalize(p);
      float sunUp = dot(up, sun);
      float day = smoothstep(-0.1, 0.2, sunUp);
      float warm = 1.0 - smoothstep(0.0, 0.3, sunUp);
      vec3 sunLight = (cloudColor * day) * (vec3(1.0) - warm * (vec3(1.0) - vec3(1.0, 0.62, 0.42)));
      float h = clamp((length(p) - radius) / thickness, 0.0, 1.0);
      vec3 ambient = mix(night, cloudColor * vec3(0.62, 0.7, 0.82), day) * (0.55 + 0.45 * h);
      vec3 lum = sunLight * beer * (0.55 + 0.45 * powder) * phase * 1.6 + ambient * 0.5;
      float a = exp(-sigma * dt);
      S += T * lum * (1.0 - a);
      T *= a;
      if (T < 0.02) break;
    }
    t += dt;
  }
  float alpha = 1.0 - T;
  if (alpha < 0.003) discard;
  // Far cloud is lost in the haze between, summed along the eye's line as the ground's is.
  vec3 hit = o + dir * max(firstHit, t0);
  float vhd = cloudHazeDepth(length(o) - planetRadius, length(hit) - planetRadius, length(hit - o));
  alpha *= exp(-vhd * vhd * 1.4427);
  // The light the cloud gives, brought into what a screen shows as the sky's is; multiplied by its alpha, so layers
  // marched into a target of their own sum there as they would over the scene.
  gl_FragColor = vec4((1.0 - exp(-1.4 * S / max(1.0 - T, 1e-4))) * alpha, alpha);
}`;

const VOLUME_FRAGMENT_WGSL = `
varying vWorld: vec3f;
uniform eye: vec3f;
uniform centre: vec3f;
uniform toPlanet: mat4x4f;
uniform sunDirection: vec3f;
uniform radius: f32;
uniform thickness: f32;
uniform cover: f32;
uniform size: f32;
uniform wind: f32;
uniform time: f32;
uniform cloudColor: vec3f;
uniform opacity: f32;
uniform octaves: f32;
uniform hazeBeta: f32;
uniform hazeHeight: f32;
uniform planetRadius: f32;
uniform baseVariety: f32;
uniform steps: f32;
uniform lightSteps: f32;
${NOISE_WGSL}
${CLOUD_BASE_WGSL}
fn cloudHazeDepth(a0: f32, a1: f32, len: f32) -> f32 {
  if (uniforms.hazeBeta <= 0.0 || len <= 0.0) { return 0.0; }
  let u0 = max(a0, 0.0) / uniforms.hazeHeight;
  let u1 = max(a1, 0.0) / uniforms.hazeHeight;
  let du = u1 - u0;
  if (abs(du) < 1e-4) { return uniforms.hazeBeta * len * exp(-u0); }
  return uniforms.hazeBeta * len * (exp(-u0) - exp(-u1)) / du;
}
fn cloudSphereHit(o: vec3f, d: vec3f, r: f32) -> vec2f {
  let b = dot(o, d);
  let c = dot(o, o) - r * r;
  let disc = b * b - c;
  if (disc < 0.0) { return vec2f(1e20, -1e20); }
  let s = sqrt(disc);
  return vec2f(-b - s, -b + s);
}
fn cloudVolume(p: vec3f) -> f32 {
  let r = length(p);
  let h = (r - uniforms.radius) / uniforms.thickness;
  if (h < 0.0 || h > 1.0) { return 0.0; }
  let d = normalize((uniforms.toPlanet * vec4f(p / r, 0.0)).xyz);
  let c = cloudDensityOf(d, uniforms.radius, uniforms.cover, uniforms.size, uniforms.wind, uniforms.time, 4.0);
  if (c <= 0.0) { return 0.0; }
  let b = cloudBaseOf(d, uniforms.radius, uniforms.size, uniforms.wind, uniforms.time, uniforms.baseVariety, c);
  let hc = (h - b) / (1.0 - b);
  if (hc < 0.0) { return 0.0; }
  let turn = uniforms.time * uniforms.wind / uniforms.radius;
  let cs = cos(turn);
  let sn = sin(turn);
  let pp = (uniforms.toPlanet * vec4f(p, 0.0)).xyz;
  let q = vec3f(pp.x * cs + pp.z * sn, pp.y, pp.z * cs - pp.x * sn) * (8.3 / uniforms.size);
  let n = (cloudValueNoise(q) + 0.5 * cloudValueNoise(q * 2.0) + 0.25 * cloudValueNoise(q * 4.0)) / 1.75;
  let top = 0.25 + 0.75 * c - 0.25 * n;
  let base = c * smoothstep(0.0, 0.07, hc) * (1.0 - smoothstep(top - 0.25, top, hc));
  if (base <= 0.0) { return 0.0; }
  return clamp((base - n * 0.45) / (1.0 - 0.45), 0.0, 1.0);
}
#ifdef CLOUD_DEPTH_CULL
var cloudDepthSampler: sampler;
var cloudDepth: texture_2d<f32>;
uniform cloudDepthSize: vec2f;
uniform cameraForward: vec3f;
fn cloudGroundInFront(px: vec2f, shellZ: f32) -> bool {
  for (var y: i32 = -1; y <= 1; y++) {
    for (var x: i32 = -1; x <= 1; x++) {
      let z = textureSampleLevel(cloudDepth, cloudDepthSampler, (px + vec2f(f32(x), f32(y))) / uniforms.cloudDepthSize, 0.0).r;
      if (z <= 0.0 || z >= shellZ || z >= ${CLOUD_DEPTH_TRUSTED_M.toFixed(1)}) { return false; }
    }
  }
  return true;
}
#endif
fn cloudPhase(mu: f32, g: f32) -> f32 {
  let g2 = g * g;
  return (1.0 - g2) / pow(1.0 + g2 - 2.0 * g * mu, 1.5);
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  if (uniforms.cover <= 0.0) { discard; }
  let o = uniforms.eye - uniforms.centre;
  let dir = normalize(input.vWorld - uniforms.eye);
  let outer = cloudSphereHit(o, dir, uniforms.radius + uniforms.thickness);
  if (outer.y <= 0.0) { discard; }
  let inner = cloudSphereHit(o, dir, uniforms.radius);
  let ground = cloudSphereHit(o, dir, uniforms.planetRadius);
  var t0 = max(outer.x, 0.0);
  if (length(o) < uniforms.radius) { t0 = inner.y; }
  var t1 = outer.y;
  if (inner.x > t0 && inner.x < t1) { t1 = inner.x; }
  if (ground.x > 0.0 && ground.x < t1) { t1 = ground.x; }
  t1 = min(t1, t0 + 20000.0);
  if (t1 <= t0) { discard; }
#ifdef CLOUD_DEPTH_CULL
  if (cloudGroundInFront(fragmentInputs.position.xy, t0 * dot(dir, uniforms.cameraForward))) { discard; }
#endif
  let sun = normalize(uniforms.sunDirection);
  let mu = dot(dir, sun);
  let phase = mix(cloudPhase(mu, -0.24), cloudPhase(mu, 0.62), 0.7);
  let coarse = clamp((t1 - t0) / uniforms.steps, 50.0, 800.0);
  let fine = clamp(uniforms.thickness * 1.2 / uniforms.steps, 15.0, 200.0);
  let jitter = cloudHash(vec3f(fragmentInputs.position.xy, 17.0));
  var t = t0 + coarse * jitter;
  var inCloud = false;
  var clearRun: f32 = 0.0;
  var found: f32 = t0;
  var budget = uniforms.steps * 3.0;
  if (length(o) > uniforms.radius + uniforms.thickness * 5.0) { budget = uniforms.steps * 1.5; }
  var T: f32 = 1.0;
  var S = vec3f(0.0);
  var firstHit: f32 = -1.0;
  let night = vec3f(0.12, 0.13, 0.17);
  let lightStep = uniforms.thickness * 0.6 / uniforms.lightSteps;
  for (var i: i32 = 0; i < ${MAX_VOLUME_STEPS}; i++) {
    if (f32(i) >= budget || t > t1) { break; }
    let p = o + dir * t;
    let dens = cloudVolume(p);
    let stride = min(coarse, fine * 4.0 + (t - t0) * 0.05);
    if (!inCloud) {
      if (dens <= 0.003) { t += stride; continue; }
      inCloud = true;
      clearRun = 0.0;
      found = t;
      t = max(t - stride, t0);
      continue;
    }
    let dt = fine;
    if (dens <= 0.003) {
      if (t > found) { clearRun += 1.0; }
      if (clearRun > 4.0) { inCloud = false; }
    } else {
      clearRun = 0.0;
      if (firstHit < 0.0) { firstHit = t; }
      let sigma = dens * 0.015 * uniforms.opacity;
      var toward: f32 = 0.0;
      for (var j: i32 = 0; j < ${MAX_VOLUME_LIGHT_STEPS}; j++) {
        if (f32(j) >= uniforms.lightSteps) { break; }
        toward += cloudVolume(p + sun * lightStep * (f32(j) + 0.5)) * lightStep;
      }
      let beer = exp(-toward * 0.015 * uniforms.opacity);
      let powder = 1.0 - exp(-dens * 6.0);
      let up = normalize(p);
      let sunUp = dot(up, sun);
      let day = smoothstep(-0.1, 0.2, sunUp);
      let warm = 1.0 - smoothstep(0.0, 0.3, sunUp);
      let sunLight = (uniforms.cloudColor * day) * (vec3f(1.0) - warm * (vec3f(1.0) - vec3f(1.0, 0.62, 0.42)));
      let h = clamp((length(p) - uniforms.radius) / uniforms.thickness, 0.0, 1.0);
      let ambient = mix(night, uniforms.cloudColor * vec3f(0.62, 0.7, 0.82), day) * (0.55 + 0.45 * h);
      let lum = sunLight * beer * (0.55 + 0.45 * powder) * phase * 1.6 + ambient * 0.5;
      let a = exp(-sigma * dt);
      S += T * lum * (1.0 - a);
      T *= a;
      if (T < 0.02) { break; }
    }
    t += dt;
  }
  var alpha = 1.0 - T;
  if (alpha < 0.003) { discard; }
  let hit = o + dir * max(firstHit, t0);
  let vhd = cloudHazeDepth(length(o) - uniforms.planetRadius, length(hit) - uniforms.planetRadius, length(hit - o));
  alpha *= exp(-vhd * vhd * 1.4427);
  fragmentOutputs.color = vec4f((1.0 - exp(-1.4 * S / max(1.0 - T, 1e-4))) * alpha, alpha);
}`;

// ---- The volume laid over the scene from the target it was marched into, at a fraction of the screen. ----
// Drawn on the layer's own sphere, so the scene's depth cuts it against the ground at full resolution, as it cut the march.

const LAY_VERTEX_GLSL = `
precision highp float;
attribute vec3 position;
uniform mat4 worldViewProjection;
void main(void) {
  gl_Position = worldViewProjection * vec4(position, 1.0);
}`;

const LAY_FRAGMENT_GLSL = `
precision highp float;
uniform sampler2D cloudTarget;
uniform vec2 screenSize;
void main(void) {
  gl_FragColor = texture2D(cloudTarget, gl_FragCoord.xy / screenSize);
}`;

const LAY_VERTEX_WGSL = `
attribute position: vec3f;
uniform worldViewProjection: mat4x4f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  vertexOutputs.position = uniforms.worldViewProjection * vec4f(vertexInputs.position, 1.0);
}`;

const LAY_FRAGMENT_WGSL = `
var cloudTargetSampler: sampler;
var cloudTarget: texture_2d<f32>;
uniform screenSize: vec2f;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  fragmentOutputs.color = textureSampleLevel(cloudTarget, cloudTargetSampler, fragmentInputs.position.xy / uniforms.screenSize, 0.0);
}`;

export interface CloudShaderSources {
  shaderLanguage: ShaderLanguage;
  vertexSource: string;
  fragmentSource: string;
}

/** The lay-over of a volume marched into its own target: WGSL on WebGPU, GLSL elsewhere. */
export function selectCloudCompositeSources(engineKind?: string): CloudShaderSources {
  return engineKind === 'webgpu'
    ? { shaderLanguage: ShaderLanguage.WGSL, vertexSource: LAY_VERTEX_WGSL, fragmentSource: LAY_FRAGMENT_WGSL }
    : { shaderLanguage: ShaderLanguage.GLSL, vertexSource: LAY_VERTEX_GLSL, fragmentSource: LAY_FRAGMENT_GLSL };
}

/** WGSL on WebGPU, natively; GLSL on every other engine: the flat layer, or with `volume`, the layer marched as a volume. */
export function selectCloudShaderSources(engineKind?: string, volume = false): CloudShaderSources {
  return engineKind === 'webgpu'
    ? { shaderLanguage: ShaderLanguage.WGSL, vertexSource: VERTEX_WGSL, fragmentSource: volume ? VOLUME_FRAGMENT_WGSL : FRAGMENT_WGSL }
    : { shaderLanguage: ShaderLanguage.GLSL, vertexSource: VERTEX_GLSL, fragmentSource: volume ? VOLUME_FRAGMENT_GLSL : FRAGMENT_GLSL };
}

/**
 * One layer, drawn as a flat sheet, or with `opts.volume` marched as a volume
 * through its shell: `steps` along the eye's line and `lightSteps` toward the
 * sun at each step. A volume is drawn on its shell's outer sphere, from the
 * side the eye looks through: the near side from outside it, the far side
 * from within.
 *
 * With a `volume.scale` under 1, the volume is marched into a target of its
 * own, that share of the screen's width and height, before the scene is
 * drawn; and the scene lays it over itself on the same sphere, read back
 * smoothly at each pixel. The march along a pixel's line does not depend on
 * what stands in front of it, so the coarser target has nothing to bleed at
 * the ground's edge: the sphere's own depth test cuts the clouds against the
 * ground at full resolution, as it did when the march was drawn straight on.
 */
export function createClouds(scene: Scene, layer: CloudLayer, opts: { engineKind?: string; octaves: number; volume?: { steps: number; lightSteps: number; scale?: number } }): CloudsHandle {
  const volume = opts.volume;
  const sources = selectCloudShaderSources(opts.engineKind, !!volume);
  // A unit sphere, scaled to the layer, so the world can move the layer without a new mesh.
  const mesh = CreateSphere('clouds', { diameter: 2, segments: 192 }, scene);
  mesh.isPickable = false;
  mesh.applyFog = false;
  mesh.alphaIndex = CLOUD_ALPHA_INDEX;
  const scale = volume ? Math.min(1, Math.max(0.1, volume.scale ?? 1)) : 1;
  // Marched into a target of its own, it passes over the pixels the ground hides, by the ground's depth at the target's size.
  const cull = scale < 1;
  const material = new ShaderMaterial(
    'clouds',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: sources.fragmentSource },
    {
      attributes: ['position'],
      uniforms: [...(volume ? CLOUD_VOLUME_UNIFORMS : CLOUD_UNIFORMS), ...(cull ? ['cloudDepthSize', 'cameraForward'] : [])],
      samplers: cull ? ['cloudDepth'] : [],
      defines: cull ? ['#define CLOUD_DEPTH_CULL'] : [],
      needAlphaBlending: true,
      shaderLanguage: sources.shaderLanguage,
    },
  );
  // A sheet is seen from both sides; a volume from one side of its outer sphere at a time, so each pixel marches once.
  material.backFaceCulling = !!volume;
  if (volume) {
    material.setFloat('steps', Math.max(1, Math.min(volume.steps, MAX_VOLUME_STEPS)));
    material.setFloat('lightSteps', Math.max(1, Math.min(volume.lightSteps, MAX_VOLUME_LIGHT_STEPS)));
    // The volume gives its colour already multiplied by its alpha.
    material.alphaMode = Constants.ALPHA_PREMULTIPLIED_PORTERDUFF;
  }
  material.disableDepthWrite = true;
  material.setFloat('octaves', Math.max(1, Math.min(opts.octaves, MAX_OCTAVES)));
  const offscreen = cull ? createOffscreenVolume(scene, mesh, material, scale, opts.engineKind) : undefined;
  mesh.material = offscreen?.lay ?? material;
  let outerRadius = layer.radius;
  // The layer's own opacity, and how much of it is drawn now: clouds fade in with the air as the eye comes into the hold.
  let layerOpacity = 1;
  let strengthNow = 1;
  const setLayer = (l: CloudLayer) => {
    outerRadius = volume ? l.radius + l.thickness : l.radius;
    mesh.scaling.setAll(outerRadius);
    material.setFloat('radius', l.radius);
    material.setFloat('thickness', Math.max(1, l.thickness));
    material.setFloat('cover', l.cover);
    material.setFloat('size', l.size);
    material.setFloat('wind', l.wind);
    layerOpacity = l.opacity;
    material.setFloat('opacity', layerOpacity * strengthNow);
    material.setFloat('baseVariety', l.baseVariety);
    material.setColor3('cloudColor', new Color3(...l.color));
  };
  setLayer(layer);
  return {
    setLayer,
    update(eye, centre, toPlanet, sun, timeS, haze, strength = 1, drawn) {
      if (strength !== strengthNow) {
        strengthNow = strength;
        material.setFloat('opacity', layerOpacity * strengthNow);
      }
      // Where the layer is drawn, and as much smaller as its planet; the sums are made where it would be at its own size.
      mesh.position.copyFrom(drawn?.centre ?? centre);
      mesh.scaling.setAll(outerRadius * (drawn?.scale ?? 1));
      // From outside the shell, its near side; from within, its far side.
      if (volume) material.cullBackFaces = Vector3.Distance(eye, centre) > outerRadius;
      offscreen?.update(material.cullBackFaces);
      material.setVector3('eye', eye);
      material.setVector3('centre', centre);
      material.setMatrix('toPlanet', toPlanet);
      material.setVector3('sunDirection', sun);
      material.setFloat('time', timeS);
      material.setFloat('hazeBeta', haze.beta);
      material.setFloat('hazeHeight', haze.height);
      material.setFloat('planetRadius', haze.planetRadius);
    },
    isReady: () => material.isReady(mesh) && (offscreen?.lay.isReady(mesh) ?? true),
    setGroup(id) {
      mesh.renderingGroupId = id;
    },
    setOutside(on) {
      // A volume is drawn from one side already; a sheet seen from within, from both.
      material.backFaceCulling = on || !!volume;
      material.zOffsetUnits = on ? -OUTSIDE_DEPTH_UNITS : 0;
    },
    setEnabled(on) {
      mesh.setEnabled(on);
    },
    dispose() {
      offscreen?.dispose();
      mesh.dispose(false, false);
      material.dispose();
    },
  };
}

/**
 * The target a volume is marched into, `scale` of the screen's width and
 * height, drawn each frame before the scene with the march on the layer's
 * sphere; and the lay-over the scene draws on that sphere instead. `update`
 * keeps the target the screen's share and the lay-over on the side of the
 * sphere the march is on.
 */
function createOffscreenVolume(scene: Scene, mesh: Mesh, march: ShaderMaterial, scale: number, engineKind?: string) {
  const engine = scene.getEngine();
  // The size the scene is drawn at: its first pass's own texture where there is one, which a temporal upscale draws
  // smaller than the screen (the march is rebuilt with the rest of the scene); else the screen's.
  const screen = () => {
    const first = scene.activeCamera?._postProcesses.find((p) => p !== null);
    if (first && first.width > 0 && first.height > 0) return { width: first.width, height: first.height };
    return { width: engine.getRenderWidth(true) || 1, height: engine.getRenderHeight(true) || 1 };
  };
  let seen = screen();
  const ground = acquireGroundDepth(scene, cloudTargetSize(seen.width, seen.height, scale));
  march.setTexture('cloudDepth', ground.map);
  // Half floats where the card can draw into them, so thin far cloud keeps its faint alpha; bytes elsewhere.
  const type = engine.getCaps().textureHalfFloatRender ? Constants.TEXTURETYPE_HALF_FLOAT : Constants.TEXTURETYPE_UNSIGNED_BYTE;
  const target = new RenderTargetTexture('clouds-target', cloudTargetSize(seen.width, seen.height, scale), scene, {
    generateMipMaps: false,
    doNotChangeAspectRatio: true,
    type,
    samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE,
    generateDepthBuffer: false,
  });
  target.wrapU = Constants.TEXTURE_CLAMP_ADDRESSMODE;
  target.wrapV = Constants.TEXTURE_CLAMP_ADDRESSMODE;
  target.clearColor = new Color4(0, 0, 0, 0);
  target.renderList = [mesh];
  target.setMaterialForRendering(mesh, march);
  scene.customRenderTargets.push(target);
  const sources = selectCloudCompositeSources(engineKind);
  const lay = new ShaderMaterial(
    'clouds-lay',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: sources.fragmentSource },
    { attributes: ['position'], uniforms: ['worldViewProjection', 'screenSize'], samplers: ['cloudTarget'], needAlphaBlending: true, shaderLanguage: sources.shaderLanguage },
  );
  lay.setTexture('cloudTarget', target);
  lay.alphaMode = Constants.ALPHA_PREMULTIPLIED_PORTERDUFF;
  lay.backFaceCulling = true;
  lay.disableDepthWrite = true;
  lay.setVector2('screenSize', new Vector2(seen.width, seen.height));
  // The march is read by the pixel's place on the target the lay-over is drawn into: the scene's, which a temporal
  // upscale draws smaller than the screen.
  lay.onBindObservable.add(() => lay.getEffect()?.setFloat2('screenSize', engine.getRenderWidth() || 1, engine.getRenderHeight() || 1));
  return {
    lay,
    update(cullBackFaces: boolean) {
      lay.cullBackFaces = cullBackFaces;
      const now = screen();
      const size = cloudTargetSize(now.width, now.height, scale);
      if (now.width !== seen.width || now.height !== seen.height) {
        seen = now;
        target.resize(size);
        lay.setVector2('screenSize', new Vector2(now.width, now.height));
      }
      ground.fit(size);
      march.setVector2('cloudDepthSize', new Vector2(size.width, size.height));
      const camera = scene.activeCamera;
      if (camera) march.setVector3('cameraForward', camera.getDirection(Vector3.Forward()));
    },
    dispose() {
      const i = scene.customRenderTargets.indexOf(target);
      if (i >= 0) scene.customRenderTargets.splice(i, 1);
      target.dispose();
      lay.dispose();
      ground.release();
    },
  };
}

interface GroundDepth {
  /** The ground's camera-space depth, metres ahead of the camera; 0 where nothing was drawn. */
  map: RenderTargetTexture;
  /** Keep the map this size. */
  fit(size: { width: number; height: number }): void;
  /** One layer fewer reads it; the last stops drawing it. */
  release(): void;
}

const groundDepths = new WeakMap<Scene, { depth: GroundDepth; users: number }>();

/**
 * The ground's depth, `size` texels, drawn each frame before any cloud
 * target, shared by every layer marched in the scene: the opaque meshes the
 * camera saw, their distance ahead of it, sampled nearest.
 */
function acquireGroundDepth(scene: Scene, size: { width: number; height: number }): GroundDepth {
  const held = groundDepths.get(scene);
  if (held) {
    held.users++;
    return held.depth;
  }
  const engine = scene.getEngine();
  const type = engine.getCaps().textureHalfFloatRender ? Constants.TEXTURETYPE_HALF_FLOAT : Constants.TEXTURETYPE_FLOAT;
  const map = new RenderTargetTexture('clouds-depth', size, scene, {
    generateMipMaps: false,
    doNotChangeAspectRatio: true,
    type,
    samplingMode: Constants.TEXTURE_NEAREST_SAMPLINGMODE,
    generateDepthBuffer: true,
  });
  const renderer = new DepthRenderer(scene, type, null, false, Constants.TEXTURE_NEAREST_SAMPLINGMODE, true, 'clouds-depth', map);
  // The sky shows through a plant's clear texels.
  testCutoutsByTheirPicture(renderer);
  // Only what hides the sky: the meshes the camera saw last that are drawn opaque.
  const opaque: AbstractMesh[] = [];
  let chosenFor = -1;
  map.getCustomRenderList = (_pass, seen, count) => {
    const frame = scene.getFrameId();
    if (frame === chosenFor) return opaque;
    chosenFor = frame;
    opaque.length = 0;
    for (let i = 0; i < count; i++) {
      const mesh = seen?.[i];
      if (!mesh) continue;
      if (mesh.material && !mesh.material.needAlphaBlending()) opaque.push(mesh);
    }
    return opaque;
  };
  // Before every cloud target, so each march reads this frame's ground.
  scene.customRenderTargets.unshift(map);
  // A mesh this map skips, its shader still being built, reads as open sky, and the clouds are drawn over it: a mesh
  // waits until it is drawn here (meshReadiness.ts), and asking builds its shader before it is shown.
  const removeCheck = addMeshReadyCheck(scene, (mesh) =>
    (mesh.subMeshes ?? []).every((sm) => {
      const material = sm.getMaterial();
      return !material || material.disableDepthWrite || material.needAlphaBlending() || renderer.isReady(sm, false);
    }),
  );
  let current = { ...size };
  const depth: GroundDepth = {
    map,
    fit(s) {
      if (s.width === current.width && s.height === current.height) return;
      current = { ...s };
      map.resize(s);
    },
    release() {
      const h = groundDepths.get(scene);
      if (!h || --h.users > 0) return;
      groundDepths.delete(scene);
      removeCheck();
      const i = scene.customRenderTargets.indexOf(map);
      if (i >= 0) scene.customRenderTargets.splice(i, 1);
      renderer.dispose();
      map.dispose();
    },
  };
  groundDepths.set(scene, { depth, users: 1 });
  return depth;
}

// ---- The shadows ----

const SHADOW_UNIFORMS_GLSL = `#ifdef CLOUDSHADOW
uniform vec3 cloudShadowCentre;
uniform mat4 cloudShadowToPlanet;
uniform vec3 cloudShadowSun;
uniform float cloudShadowTime;
uniform float cloudShadowOctaves;
uniform vec4 cloudShadowRadius;
uniform vec4 cloudShadowCover;
uniform vec4 cloudShadowSize;
uniform vec4 cloudShadowWind;
uniform vec4 cloudShadowStrength;
#endif
`;

const SHADOW_UNIFORMS_WGSL = `#ifdef CLOUDSHADOW
uniform cloudShadowCentre: vec3f;
uniform cloudShadowToPlanet: mat4x4f;
uniform cloudShadowSun: vec3f;
uniform cloudShadowTime: f32;
uniform cloudShadowOctaves: f32;
uniform cloudShadowRadius: vec4f;
uniform cloudShadowCover: vec4f;
uniform cloudShadowSize: vec4f;
uniform cloudShadowWind: vec4f;
uniform cloudShadowStrength: vec4f;
#endif
`;

const SHADOW_DEFINITIONS_GLSL = `#ifdef CLOUDSHADOW
${NOISE_GLSL}
// How much of the sun's direct light reaches the world point posW through the layers over it.
float cloudShadowAt(vec3 posW) {
  vec3 p = posW - cloudShadowCentre;
  vec3 s = normalize(cloudShadowSun);
  float pp = dot(p, p);
  float b = dot(p, s);
  float light = 1.0;
  for (int i = 0; i < ${MAX_SHADOW_LAYERS}; i++) {
    float r = cloudShadowRadius[i];
    float k = cloudShadowStrength[i];
    if (k <= 0.0 || pp >= r * r) continue;
    float t = -b + sqrt(b * b - (pp - r * r));
    vec3 d = normalize((cloudShadowToPlanet * vec4(normalize(p + s * t), 0.0)).xyz);
    light *= 1.0 - k * cloudDensityOf(d, r, cloudShadowCover[i], cloudShadowSize[i], cloudShadowWind[i], cloudShadowTime, cloudShadowOctaves);
  }
  return light;
}
#endif
`;

const SHADOW_DEFINITIONS_WGSL = `#ifdef CLOUDSHADOW
${NOISE_WGSL}
fn cloudShadowAt(posW: vec3f) -> f32 {
  let p = posW - uniforms.cloudShadowCentre;
  let s = normalize(uniforms.cloudShadowSun);
  let pp = dot(p, p);
  let b = dot(p, s);
  var light: f32 = 1.0;
  for (var i: i32 = 0; i < ${MAX_SHADOW_LAYERS}; i++) {
    let r = uniforms.cloudShadowRadius[i];
    let k = uniforms.cloudShadowStrength[i];
    if (k <= 0.0 || pp >= r * r) { continue; }
    let t = -b + sqrt(b * b - (pp - r * r));
    let d = normalize((uniforms.cloudShadowToPlanet * vec4f(normalize(p + s * t), 0.0)).xyz);
    light *= 1.0 - k * cloudDensityOf(d, r, uniforms.cloudShadowCover[i], uniforms.cloudShadowSize[i], uniforms.cloudShadowWind[i], uniforms.cloudShadowTime, uniforms.cloudShadowOctaves);
  }
  return light;
}
#endif
`;

export interface CloudShadowCode {
  /** Declared once, before the material's main. */
  definitions: string;
  /** In a physically based material, on its direct light only, before its colour is composed. */
  pbr: string;
  /** In a standard material, on its colour, before its fog. */
  standard: string;
}

/** The shadows' code for a material: WGSL on WebGPU, GLSL elsewhere. */
export function selectCloudShadowCode(engineKind?: string): CloudShadowCode {
  if (engineKind === 'webgpu') {
    return {
      definitions: SHADOW_DEFINITIONS_WGSL,
      pbr: `#ifdef CLOUDSHADOW
let cloudShade = cloudShadowAt(fragmentInputs.vPositionW);
finalDiffuse *= cloudShade;
#ifdef SPECULARTERM
finalSpecularScaled *= cloudShade;
#endif
#endif
`,
      standard: `#ifdef CLOUDSHADOW
color = vec4f(color.rgb * cloudShadowAt(fragmentInputs.vPositionW), color.a);
#endif
`,
    };
  }
  return {
    definitions: SHADOW_DEFINITIONS_GLSL,
    pbr: `#ifdef CLOUDSHADOW
float cloudShade = cloudShadowAt(vPositionW);
finalDiffuse *= cloudShade;
#ifdef SPECULARTERM
finalSpecularScaled *= cloudShade;
#endif
#endif
`,
    standard: `#ifdef CLOUDSHADOW
color.rgb *= cloudShadowAt(vPositionW);
#endif
`,
  };
}

/** What every plugin binds: the planet, the sun, the time and the layers, written by the handle each frame. */
interface ShadowState {
  centre: Vector3;
  toPlanet: Matrix;
  sun: Vector3;
  timeS: number;
  radius: number[];
  cover: number[];
  size: number[];
  wind: number[];
  strength: number[];
}

const PLUGIN_NAME = 'CloudShadow';

class CloudShadowPlugin extends MaterialPluginBase {
  private _isEnabled = true;

  constructor(
    material: ConstructorParameters<typeof MaterialPluginBase>[0],
    private state: ShadowState,
  ) {
    super(material, PLUGIN_NAME, 300, { CLOUDSHADOW: false }, true, true);
  }

  /** Draws from another planet's state from now on (awayMaterials.ts). */
  rebind(state: ShadowState): void {
    this.state = state;
  }

  /**
   * A physically based material, shaded in its direct light; otherwise a
   * standard one, shaded in its colour. Read from the base's material, since
   * the plugin manager asks for the code inside the base's constructor, before
   * this class's own fields are set.
   */
  private get pbr(): boolean {
    return this._material.getClassName() === 'PBRMaterial';
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'CloudShadowPlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0]): void {
    (defines as unknown as Record<string, boolean>)['CLOUDSHADOW'] = this._isEnabled;
  }

  override getUniforms(shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL) {
    return {
      ubo: [
        { name: 'cloudShadowCentre', size: 3, type: 'vec3' },
        { name: 'cloudShadowToPlanet', size: 16, type: 'mat4' },
        { name: 'cloudShadowSun', size: 3, type: 'vec3' },
        { name: 'cloudShadowTime', size: 1, type: 'float' },
        { name: 'cloudShadowOctaves', size: 1, type: 'float' },
        { name: 'cloudShadowRadius', size: 4, type: 'vec4' },
        { name: 'cloudShadowCover', size: 4, type: 'vec4' },
        { name: 'cloudShadowSize', size: 4, type: 'vec4' },
        { name: 'cloudShadowWind', size: 4, type: 'vec4' },
        { name: 'cloudShadowStrength', size: 4, type: 'vec4' },
      ],
      fragment: shaderLanguage === ShaderLanguage.WGSL ? SHADOW_UNIFORMS_WGSL : SHADOW_UNIFORMS_GLSL,
    };
  }

  override bindForSubMesh(ubo: UniformBuffer): void {
    if (!this._isEnabled) return;
    const s = this.state;
    const v4 = (a: number[]) => [a[0] ?? 0, a[1] ?? 0, a[2] ?? 0, a[3] ?? 0] as const;
    ubo.updateFloat3('cloudShadowCentre', s.centre.x, s.centre.y, s.centre.z);
    ubo.updateMatrix('cloudShadowToPlanet', s.toPlanet);
    ubo.updateFloat3('cloudShadowSun', s.sun.x, s.sun.y, s.sun.z);
    ubo.updateFloat('cloudShadowTime', s.timeS);
    ubo.updateFloat('cloudShadowOctaves', SHADOW_OCTAVES);
    ubo.updateFloat4('cloudShadowRadius', ...v4(s.radius));
    ubo.updateFloat4('cloudShadowCover', ...v4(s.cover));
    ubo.updateFloat4('cloudShadowSize', ...v4(s.size));
    ubo.updateFloat4('cloudShadowWind', ...v4(s.wind));
    ubo.updateFloat4('cloudShadowStrength', ...v4(s.strength));
  }

  override getCustomCode(shaderType: string, shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL): { [pointName: string]: string } | null {
    if (shaderType !== 'fragment') return null;
    const code = selectCloudShadowCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    // Each kind of material its own point: a physically based one has a point named for fog too,
    // where its colour is not yet the standard material's `color`.
    return this.pbr
      ? { CUSTOM_FRAGMENT_DEFINITIONS: code.definitions, CUSTOM_FRAGMENT_BEFORE_FINALCOLORCOMPOSITION: code.pbr }
      : { CUSTOM_FRAGMENT_DEFINITIONS: code.definitions, CUSTOM_FRAGMENT_BEFORE_FOG: code.standard };
  }
}

/** Lit materials: those whose shaders carry the plugin's injection points. */
const isLit = (m: Scene['materials'][number]): boolean => {
  const name = m.getClassName();
  return name === 'StandardMaterial' || name === 'PBRMaterial';
};

/**
 * Shade every lit material in the scene, and every one added later, from the
 * sun by the layers given to `setLayers` (at most four, lowest first): one
 * that arrives is shaded from the next `update`. `dispose` turns the shading
 * off on them all and adds it to no more.
 */
export function createCloudShadows(scene: Scene, _opts: { engineKind?: string }): CloudShadowsHandle {
  const state: ShadowState = {
    centre: new Vector3(0, 0, 0),
    toPlanet: Matrix.Identity(),
    sun: new Vector3(0, 1, 0),
    timeS: 0,
    radius: [],
    cover: [],
    size: [],
    wind: [],
    strength: [],
  };
  const plugins: CloudShadowPlugin[] = [];
  // Every lit material in the scene, and each one as it arrives (a tile, a chunk, a world's own): shaded from the
  // next frame.
  const arrivals = materialArrivals(scene);
  const attachAll = () =>
    arrivals.take((m) => {
      if (isLit(m) && isAway(m)) return false;
      const p = isLit(m) ? takePlugin(m, PLUGIN_NAME, state, () => new CloudShadowPlugin(m, state)) : undefined;
      if (p) plugins.push(p);
    });
  attachAll();
  let stopped = false;
  // Each layer's own shadow, and how much of it is cast now: shadows fade in with the clouds.
  let layerShadows: number[] = [];
  let strengthNow = 1;
  return {
    setLayers(layers) {
      const ls = layers.slice(0, MAX_SHADOW_LAYERS);
      state.radius = ls.map((l) => l.radius);
      state.cover = ls.map((l) => l.cover);
      state.size = ls.map((l) => l.size);
      state.wind = ls.map((l) => l.wind);
      layerShadows = ls.map((l) => l.shadow);
      state.strength = layerShadows.map((s) => s * strengthNow);
    },
    update(centre, toPlanet, sun, timeS, strength = 1) {
      if (stopped) return;
      if (strength !== strengthNow) {
        strengthNow = strength;
        state.strength = layerShadows.map((s) => s * strengthNow);
      }
      attachAll();
      state.centre.copyFrom(centre);
      state.toPlanet.copyFrom(toPlanet);
      state.sun.copyFrom(sun);
      state.timeS = timeS;
    },
    dispose() {
      stopped = true;
      arrivals.dispose();
      for (const p of plugins) p.isEnabled = false;
      plugins.length = 0;
    },
  };
}
